-- Sprint 11 (HaoKhiDongA): nội dung khởi tạo của mục Hướng dẫn sử dụng và Câu hỏi thường gặp theo vai trò (HK.HS.110, GV.080, QT.054).
-- Đây là bản nháp do hệ thống soạn từ các tính năng hiện có; quản trị tổng có thể sửa, thêm, ẩn hoặc xóa ở mục "Hướng dẫn và câu hỏi thường gặp".
-- Không chứa dữ liệu thật. Chỉ thêm mới bản ghi.

INSERT INTO public.hk_faq (audience, category, question, answer, position) VALUES
-- ------------------------------------------------------------------ chung cho mọi vai trò
('all', 'Tài khoản', 'Tôi quên mật khẩu thì làm thế nào?',
 E'Ở màn hình đăng nhập, chọn "Quên mật khẩu", nhập tên đăng nhập hoặc email. Hệ thống gửi mã OTP 6 chữ số tới email trong hồ sơ; nhập mã và đặt mật khẩu mới.\nNếu tài khoản chưa có email trong hồ sơ, hãy nhờ giáo viên hoặc quản trị viên trường đặt lại mật khẩu cho bạn.', 1),
('all', 'Tài khoản', 'Vì sao hệ thống bắt tôi đổi mật khẩu khi đăng nhập lần đầu?',
 E'Mật khẩu tạm do nhà trường cấp chỉ dùng một lần. Bạn cần đặt mật khẩu riêng (tối thiểu 8 ký tự, gồm cả chữ và số) rồi mới dùng được các mục khác.', 2),
('all', 'Tài khoản', 'Tài khoản bị khóa tạm thì sao?',
 E'Nhập sai mật khẩu 5 lần liên tiếp, tài khoản bị khóa tạm 15 phút để bảo vệ bạn. Hãy chờ rồi thử lại, hoặc dùng "Quên mật khẩu" nếu bạn không nhớ mật khẩu.', 3),
-- ------------------------------------------------------------------ học sinh
('student', 'Bắt đầu', 'Bắt đầu học từ đâu?',
 E'Mở mục "Học": đường học được chia thành các Phần (mỗi Phần là một cuộc kháng chiến), mỗi Phần có nhiều Cửa, mỗi Cửa có các nút như bài học, luyện tập, nghe kể chuyện, rương và kiểm tra cửa. Làm lần lượt từ nút đang mở; hoàn thành nút này thì nút kế tiếp mở ra.', 1),
('student', 'Bắt đầu', 'Làm bài quiz như thế nào và điểm được tính ra sao?',
 E'Mỗi câu có đồng hồ đếm ngược. Trả lời đúng được điểm của câu; trả lời nhanh được thưởng thêm (tối đa một nửa điểm câu). Điểm và đáp án do máy chủ chấm nên không thể sửa. Làm xong, bạn xem được đáp án và lời giải thích của từng câu.', 2),
('student', 'Bắt đầu', 'Làm sai nhiều thì sao? Tim là gì?',
 E'Trả lời sai làm mất tim (nếu lớp bật tim). Hết tim thì chờ hồi tim hoặc dùng vật phẩm; ôn lại các câu sai ở mục "Luyện tập" là cách tốt nhất để lấy lại phong độ.', 3),
('student', 'Trò chơi hóa', 'Điểm, vàng, Binh thư và thẻ tướng dùng để làm gì?',
 E'Điểm giúp bạn lên cấp và leo bảng xếp hạng. Vàng dùng mua vật phẩm trong "Cửa hàng". Binh thư là tài nguyên thưởng khi hoàn thành nút học, dùng để nâng cấp thẻ tướng trong "Bộ thẻ". Thẻ tướng dùng khi hành quân và đánh trận trong mục "Chiến dịch" và "Trận đánh".', 4),
('student', 'Trò chơi hóa', 'Chuỗi ngày học hoạt động ra sao?',
 E'Mỗi ngày bạn đạt mục tiêu điểm thì chuỗi tăng thêm một. Bỏ lỡ một ngày, chuỗi về 0 trừ khi bạn dùng vật phẩm bảo vệ chuỗi. Bạn có thể bật nhắc học ở "Cài đặt" để không quên.', 5),
('student', 'Lớp học', 'Làm sao để vào lớp của giáo viên?',
 E'Vào mục "Lớp học" (trong "Xem thêm"), mục "Tham gia lớp bằng mã": nhập mã lớp do giáo viên cung cấp rồi bấm "Vào lớp". Khi vào lớp, bạn nhận bài tập, thông báo và có thể được chia vào đội.', 6),
('student', 'Lớp học', 'Tôi thấy bài tập của lớp ở đâu?',
 E'Mục "Lớp học" → "Bài tập" liệt kê các bài giáo viên giao kèm hạn nộp. Bài sắp đến hạn còn hiện trong "Gợi ý học tập" và có thông báo nhắc.', 7),
('student', 'Tiểu Tướng (AI)', 'Hỏi Tiểu Tướng có an toàn và chính xác không?',
 E'Tiểu Tướng chỉ trả lời dựa trên tư liệu lịch sử đã được kiểm duyệt trong hệ thống và ghi rõ nguồn; câu hỏi ngoài phạm vi bị từ chối. Mỗi ngày bạn có số lượt hỏi nhất định. Nếu thấy câu trả lời chưa đúng, hãy bấm "Báo cáo" để quản trị viên kiểm tra lại.', 8),
('student', 'Thi đấu', 'Tham gia phòng thi đấu bằng cách nào?',
 E'Mục "Thi đấu" (trong "Xem thêm"): nhập mã PIN 6 số của phòng do giáo viên cung cấp, hoặc quét mã QR giáo viên chiếu trên màn hình. Trả lời đúng và nhanh để được nhiều điểm; kết quả hiện sau mỗi câu.', 9),
('student', 'Cài đặt', 'Đổi giao diện sáng / tối và bật nhắc học ở đâu?',
 E'Bấm biểu tượng bánh răng cạnh chuông thông báo để mở "Cài đặt": chọn giao diện sáng, tối hoặc theo thiết bị; chọn giờ nhắc học và kênh nhận (thông báo trên web, email hoặc cả hai). Lựa chọn lưu theo tài khoản nên dùng được trên mọi thiết bị.', 10),
('student', 'Hỗ trợ', 'Gặp lỗi hoặc có góp ý thì gửi cho ai?',
 E'Mục "Trợ giúp" (trong "Xem thêm") → "Gửi phản hồi": mô tả vấn đề và đính kèm ảnh chụp màn hình nếu có. Quản trị viên sẽ phản hồi và bạn theo dõi được trạng thái xử lý ngay trong mục này.', 11),
-- ------------------------------------------------------------------ giáo viên
('teacher', 'Lớp học', 'Tạo lớp và mời học sinh vào lớp thế nào?',
 E'Mục "Lớp học" → "Tạo lớp": đặt tên, chọn năm học và khối. Hệ thống tạo mã lớp 6 ký tự; học sinh nhập mã trong mục "Lớp học" của mình để tham gia. Bạn cũng có thể thêm học sinh có sẵn trong trường, chia đội và đặt luật lớp.', 1),
('teacher', 'Nội dung', 'Thiết kế hành trình học cho lớp như thế nào?',
 E'Mục "Hành trình học": chọn hành trình mẫu, bấm "Nhân bản" để chỉnh theo lớp, sắp xếp Phần – Cửa – nút, đặt điều kiện mở và lịch mở, rồi "Giao cho lớp". Hành trình đã có học sinh làm thì nhân bản để chỉnh thay vì sửa trực tiếp.', 2),
('teacher', 'Nội dung', 'Soạn câu hỏi và bộ đề ở đâu?',
 E'Mục "Ngân hàng câu hỏi" để soạn từng câu (một đáp án, nhiều đáp án, đúng/sai, điền khuyết, sắp xếp, kéo thả bản đồ…); mục "Bộ đề" để ghép câu thành đề. Muốn nhanh hơn, dùng "Trợ lý AI" → "Soạn câu hỏi" để có bản nháp rồi sửa và lưu.', 3),
('teacher', 'Bài tập', 'Giao bài tập và chấm điểm như thế nào?',
 E'Vào lớp → "Bài tập" → "Giao bài": chọn bộ đề, mini-game hoặc bài học, đặt hạn nộp và thưởng đúng hạn. Hệ thống tự chấm bài quiz; bạn có thể nhập điểm và nhận xét riêng cho từng học sinh, nhắc học sinh chưa làm.', 4),
('teacher', 'Thi đấu', 'Tổ chức thi đấu trực tiếp trên lớp ra sao?',
 E'Mục "Thi đấu trực tiếp" → tạo phòng từ một bộ đề, chọn lớp. Chiếu màn hình có mã PIN và mã QR cho học sinh; bấm bắt đầu, điều khiển từng câu và xem bảng xếp hạng. Kết thúc, tải báo cáo trận ở dạng PDF hoặc Excel.', 5),
('teacher', 'Báo cáo', 'Xem tiến độ lớp và học sinh cần hỗ trợ ở đâu?',
 E'Mục "Thống kê lớp": tổng quan lớp, danh sách học sinh, báo cáo theo chủ đề và danh sách học sinh cần hỗ trợ (gợi ý theo quy tắc, bạn quyết định cách hỗ trợ). Có thể xuất báo cáo Excel hoặc PDF và gửi nhận xét qua email cho học sinh, phụ huynh.', 6),
('teacher', 'Thông báo', 'Gửi thông báo tới lớp và đặt lịch gửi?',
 E'Mục "Thông báo": soạn tiêu đề và nội dung, chọn một hoặc nhiều lớp, gửi ngay hoặc đặt giờ gửi. Thông báo chưa gửi sửa hoặc hủy được; thông báo đã gửi có thể sửa nội dung hoặc thu hồi.', 7),
('teacher', 'Hỗ trợ', 'Gặp lỗi hệ thống thì báo ở đâu?',
 E'Mục "Trợ giúp" → "Gửi yêu cầu hỗ trợ". Quản trị viên tổng phản hồi và bạn xem lại trạng thái xử lý ngay trong mục này.', 8),
-- ------------------------------------------------------------------ quản trị viên trường học
('school_admin', 'Trường và năm học', 'Thiết lập năm học và khối lớp như thế nào?',
 E'Mục "Trường và năm học": tạo năm học (một năm đang hoạt động tại một thời điểm), cập nhật thông tin trường. Năm học đã kết thúc chuyển sang chỉ xem.', 1),
('school_admin', 'Tài khoản', 'Tạo tài khoản giáo viên, học sinh hàng loạt?',
 E'Mục "Giáo viên" hoặc "Học sinh" → "Nhập Excel": tải tệp mẫu, điền dữ liệu, tải lên và xem trước kết quả trước khi xác nhận. Mật khẩu tạm được gửi qua email nếu có, hoặc hiện một lần cho bạn. Số học sinh tối đa của trường do quản trị tổng cấu hình.', 2),
('school_admin', 'Lớp học', 'Xếp lớp, chuyển lớp và mở lại lớp?',
 E'Mục "Lớp học": tạo lớp theo năm học, gán giáo viên, thêm / chuyển / bớt học sinh. Lớp đã đóng chỉ xem; có thể mở lại khi cần.', 3),
('school_admin', 'Nội dung', 'Duyệt nội dung của giáo viên gửi lên?',
 E'Mục "Duyệt nội dung": xem câu hỏi, bộ đề, hành trình giáo viên đề xuất; duyệt để đưa vào kho của trường (nội dung được sao sang kho trường, giáo viên vẫn tự sửa bản của mình) hoặc từ chối kèm lý do.', 4),
('school_admin', 'Báo cáo', 'Xem báo cáo của trường và xuất file?',
 E'Mục "Báo cáo": tổng quan, hồ sơ từng học sinh, kết quả theo khối / lớp / giáo viên có xếp hạng, mức độ sử dụng theo ngày / tuần / tháng và thống kê AI; xuất Excel hoặc PDF.', 5),
('school_admin', 'Thông báo', 'Gửi thông báo cho cả trường, một khối hoặc một số lớp?',
 E'Mục "Thông báo của trường": chọn phạm vi (cả trường, theo khối hoặc theo lớp), có thể chọn chỉ gửi cho học sinh hoặc giáo viên, gửi ngay hoặc đặt lịch. Thông báo chưa gửi sửa / xóa được.', 6),
('school_admin', 'Khảo sát', 'Tạo khảo sát trải nghiệm cho học sinh, giáo viên?',
 E'Mục "Khảo sát": chọn mẫu của hệ thống hoặc tự soạn câu hỏi, chọn đối tượng và lớp, đặt thời gian mở – đóng. Xem biểu đồ tổng hợp và xuất dữ liệu thô (không chứa tên người trả lời) khi khảo sát có kết quả.', 7),
('school_admin', 'Nhật ký', 'Xem ai đã làm gì trong trường?',
 E'Mục "Nhật ký": danh sách thao tác (tạo, sửa, xóa tài khoản, lớp, nội dung) kèm người thực hiện và thời điểm, lọc theo người, thao tác và kết quả; xem thêm lịch sử đăng nhập của người dùng trong trường.', 8),
('school_admin', 'Hỗ trợ', 'Gửi yêu cầu hỗ trợ tới quản trị tổng?',
 E'Mục "Trợ giúp" → "Gửi yêu cầu hỗ trợ": mô tả vấn đề, đính kèm ảnh chụp màn hình nếu có và theo dõi trạng thái xử lý (Mới / Đang xử lý / Đã xong).', 9);
